def summarize_rows(rows, threshold):
    """Filter rows and compute summary statistics."""
    valid_rows = []
    for row in rows:
        if row["value"] is None:
            continue
        if row["value"] < threshold:
            continue
        valid_rows.append(row)
    total = 0
    for row in valid_rows:
        total += row["value"]
    mean = total / len(valid_rows) if valid_rows else 0.0
    largest = max((row["value"] for row in valid_rows), default=0.0)
    smallest = min((row["value"] for row in valid_rows), default=0.0)
    return {
        "count": len(valid_rows),
        "total": total,
        "mean": mean,
        "largest": largest,
        "smallest": smallest,
    }


def print_report(rows, threshold):
    summary = summarize_rows(rows, threshold)
    for key, value in summary.items():
        print(f"{key}: {value}")

